def is_permutation(coeffs, m):
    # coeffs is (a3, a2, a1, a0)
    # but we only care about P(x) = a3*x^3 + a1*x
    # because we already know a2=0 and a0=0
    a3, a1 = coeffs
    seen = [False] * m
    for x in range(m):
        val = (a3 * x**3 + a1 * x) % m
        if seen[val]:
            return False
        seen[val] = True
    return True

def count_permutations(m):
    count = 0
    for a3 in range(m):
        for a1 in range(m):
            if is_permutation((a3, a1), m):
                count += 1
    return count

print(f"N11: {count_permutations(11)}")
print(f"N61: {count_permutations(61)}")

